const items = $input.all();
const isWebhook = Boolean(items[0]?.json?.body !== undefined || items[0]?.json?.headers !== undefined);
const body = items[0]?.json?.body || items[0]?.json || {};

const daysThreshold = Number(body.days_threshold) || 30;
const targetCompany = body.company_name || null;

return [{
  json: {
    trigger_mode: isWebhook ? 'ON_DEMAND_WEBHOOK' : 'SCHEDULED_CRON',
    days_threshold: daysThreshold,
    target_company: targetCompany,
    triggered_at: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'NO_EXPIRING_CONTRACTS',
    message: 'Không có hợp đồng nào hết hạn trong phạm vi ngày đã chọn.',
    total_found: 0,
    evaluated_at: new Date().toISOString()
  }
}];

const items = $input.all();

return items.map(entry => {
  const item = entry.json;
  const days = Number(item.days_remaining) || 0;
  const health = Number(item.health_score) || 70;
  const churn = (item.churn_risk || 'MEDIUM').toUpperCase();
  const value = Number(item.contract_value) || 0;

  let priority = 'LOW';
  let riskAssessment = 'Ổn định';

  if (days <= 7 || (days <= 14 && churn === 'HIGH')) {
    priority = 'URGENT';
    riskAssessment = 'Rủi ro rời bỏ rất cao hoặc thời hạn quá gấp';
  } else if (days <= 15 || health < 50) {
    priority = 'HIGH';
    riskAssessment = 'Cần can thiệp chăm sóc khẩn cấp trước khi hết hạn';
  } else if (days <= 30) {
    priority = 'MEDIUM';
    riskAssessment = 'Chu kỳ nhắc nhở gia hạn thông thường';
  }

  return {
    json: {
      ...item,
      evaluated_days: days,
      priority: priority,
      risk_assessment: riskAssessment,
      is_high_value: value >= 50000000
    }
  };
});

const items = $input.all();

return items.map(entry => {
  const item = entry.json;
  let discountOffer = 0;
  let recommendedAction = '';

  switch (item.priority) {
    case 'URGENT':
      discountOffer = item.is_high_value ? 15 : 10;
      recommendedAction = `CẢNH BÁO KHẨN: Chỉ còn ${item.evaluated_days} ngày. Điều phối Trưởng phòng Sales gọi trực tiếp, áp dụng ưu đãi gia hạn sớm ${discountOffer}%.`;
      break;
    case 'HIGH':
      discountOffer = item.is_high_value ? 10 : 5;
      recommendedAction = `Sắp xếp cuộc họp review hiệu quả dịch vụ quý, gửi đề xuất gia hạn kèm ưu đãi ${discountOffer}%.`;
      break;
    case 'MEDIUM':
      discountOffer = 5;
      recommendedAction = `Gửi email thông báo gia hạn định kỳ (còn ${item.evaluated_days} ngày) và tài liệu tính năng mới.`;
      break;
    default:
      recommendedAction = 'Gửi thư cảm ơn và khảo sát mức độ hài lòng khách hàng định kỳ.';
  }

  return {
    json: {
      ...item,
      discount_offer: discountOffer,
      recommended_action: recommendedAction,
      task_title: `[Gia hạn hợp đồng] ${item.company_name || 'Khách hàng'} - Còn ${item.evaluated_days} ngày (${item.priority})`
    }
  };
});

const evaluatedList = $('Code (Tailor Renewal Offer & Action)').all();

return evaluatedList.map(entry => {
  const item = entry.json;
  const isEscalationNeeded = (item.priority === 'URGENT' || item.priority === 'HIGH');

  const alertBody = `🚨 *THÔNG BÁO THEO DÕI HỢP ĐỒNG SẮP HẾT HẠN (WF-18)*\n` +
    `• *Khách hàng:* ${item.company_name || 'N/A'}\n` +
    `• *Hợp đồng:* \`${item.contract_id || 'N/A'}\`\n` +
    `• *Ngày kết thúc:* ${item.contract_end_date} (*Còn ${item.evaluated_days} ngày*)\n` +
    `• *Mức độ ưu tiên:* *${item.priority}*\n` +
    `• *Đề xuất chiết khấu:* ${item.discount_offer}%\n` +
    `• *Hành động:* ${item.recommended_action}`;

  return {
    json: {
      ...item,
      is_escalation_needed: isEscalationNeeded,
      alert_message: alertBody
    }
  };
});

const items = $input.all();

return items.map(entry => {
  const item = entry.json;
  return {
    json: {
      ...item,
      dispatch_channel: 'SLACK_AND_JIRA_ESCALATION',
      escalation_status: 'DISPATCHED_TO_LEADERSHIP',
      escalated_at: new Date().toISOString()
    }
  };
});

const allItems = $('Code (Format Renewal Alerts)').all();
const urgentCount = allItems.filter(i => i.json.priority === 'URGENT').length;
const highCount = allItems.filter(i => i.json.priority === 'HIGH').length;
const mediumCount = allItems.filter(i => i.json.priority === 'MEDIUM').length;

return [{
  json: {
    success: true,
    message: 'Hoàn tất quy trình rà soát và cập nhật hạn hợp đồng khách hàng.',
    summary: {
      total_contracts_processed: allItems.length,
      urgent_cases: urgentCount,
      high_priority_cases: highCount,
      medium_cases: mediumCount,
      processed_at: new Date().toISOString()
    },
    contracts_detail: allItems.map(i => ({
      customer_id: i.json.id,
      company_name: i.json.company_name,
      contract_id: i.json.contract_id,
      days_remaining: i.json.evaluated_days,
      priority: i.json.priority,
      discount_offer: i.json.discount_offer,
      recommended_action: i.json.recommended_action
    }))
  }
}];
